-- Explicit synthetic identities from rtn-managed/fixture.sql. No live Auth.
SET ROLE postgres;
SELECT lab.keep('draft_attempt_id',lab.ctx('attempt2')->'attempt_id');
SELECT lab.keep('draft_original_attempt_hash',(SELECT to_jsonb(md5(to_jsonb(t)::text)) FROM rtn_private.attempts t WHERE id=(lab.ctx('draft_attempt_id')#>>'{}')::uuid));
SELECT lab.keep('draft_answers',(SELECT jsonb_build_object(q->>'id',jsonb_build_array(q->'options'->0->>'id')) FROM rtn_private.attempts t CROSS JOIN LATERAL(SELECT t.question_snapshot->0 q)x WHERE t.id=(lab.ctx('draft_attempt_id')#>>'{}')::uuid));
SELECT lab.keep('draft_other_answers',(SELECT jsonb_build_object(q->>'id',jsonb_build_array(q->'options'->1->>'id')) FROM rtn_private.attempts t CROSS JOIN LATERAL(SELECT t.question_snapshot->0 q)x WHERE t.id=(lab.ctx('draft_attempt_id')#>>'{}')::uuid));
SELECT lab.check('draft: no direct table grant',NOT has_table_privilege('authenticated','rtn_private.attempt_drafts','SELECT') AND NOT has_table_privilege('authenticated','rtn_private.attempt_drafts','UPDATE'));
SELECT lab.check('draft: role ACL denies anon and service',NOT has_function_privilege('anon','public.get_rtn_attempt_draft(uuid)','EXECUTE') AND NOT has_function_privilege('service_role','public.save_rtn_attempt_draft(uuid,jsonb,bigint)','EXECUTE'));
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',false);
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000102',false);
SELECT lab.denied('draft: foreign learner cannot read',format('SELECT public.get_rtn_attempt_draft(%L)',lab.ctx('draft_attempt_id')#>>'{}'));
SELECT lab.denied('draft: foreign learner cannot write',format('SELECT public.save_rtn_attempt_draft(%L,%L,0)',lab.ctx('draft_attempt_id')#>>'{}',lab.ctx('draft_answers')));
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',false);
SELECT lab.denied('draft: owner cannot impersonate learner',format('SELECT public.get_rtn_attempt_draft(%L)',lab.ctx('draft_attempt_id')#>>'{}'));
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000101',false);
SELECT lab.check('draft: initial read is empty revision zero',(public.get_rtn_attempt_draft((lab.ctx('draft_attempt_id')#>>'{}')::uuid)->>'revision')::integer=0);
SELECT lab.keep('draft_saved',public.save_rtn_attempt_draft((lab.ctx('draft_attempt_id')#>>'{}')::uuid,lab.ctx('draft_answers'),0));
SELECT lab.check('draft: partial answers saved at revision one',lab.ctx('draft_saved')->'answers'=lab.ctx('draft_answers') AND lab.ctx('draft_saved')->>'revision'='1');
SELECT lab.check('draft: lost response retry does not create another revision',(public.save_rtn_attempt_draft((lab.ctx('draft_attempt_id')#>>'{}')::uuid,lab.ctx('draft_answers'),0)->>'revision')::integer=1);
SELECT lab.check('draft: fresh request resumes exact saved answers',public.get_rtn_attempt_draft((lab.ctx('draft_attempt_id')#>>'{}')::uuid)->'answers'=lab.ctx('draft_answers'));
SELECT lab.denied('draft: stale different device cannot overwrite',format('SELECT public.save_rtn_attempt_draft(%L,%L,0)',lab.ctx('draft_attempt_id')#>>'{}',lab.ctx('draft_other_answers')),'40001');
SELECT lab.denied('draft: fabricated question rejected',format('SELECT public.save_rtn_attempt_draft(%L,''{"unknown-question":["yes"]}'',1)',lab.ctx('draft_attempt_id')#>>'{}'),'22023');
SELECT lab.denied('draft: fabricated option rejected',format('SELECT public.save_rtn_attempt_draft(%L,%L,1)',lab.ctx('draft_attempt_id')#>>'{}',jsonb_build_object((SELECT key FROM jsonb_each(lab.ctx('draft_answers')) LIMIT 1),jsonb_build_array('unknown-option'))),'22023');
SELECT lab.denied('draft: duplicate option rejected',format('SELECT public.save_rtn_attempt_draft(%L,%L,1)',lab.ctx('draft_attempt_id')#>>'{}',(SELECT jsonb_object_agg(key,value||value) FROM jsonb_each(lab.ctx('draft_answers')))),'22023');
SELECT lab.denied('draft: client cannot add marks or private fields',format('SELECT public.save_rtn_attempt_draft(%L,''{"score":100}'',1)',lab.ctx('draft_attempt_id')#>>'{}'),'22023');
SELECT lab.check('draft: empty selection can be saved',(public.save_rtn_attempt_draft((lab.ctx('draft_attempt_id')#>>'{}')::uuid,'{}',1)->>'revision')::integer=2);
SET ROLE postgres;
SELECT lab.check('draft: question key score status and old result unchanged',lab.ctx('draft_original_attempt_hash')=(SELECT to_jsonb(md5(to_jsonb(t)::text)) FROM rtn_private.attempts t WHERE id=(lab.ctx('draft_attempt_id')#>>'{}')::uuid));
SELECT lab.check('draft: only real nonempty changed answer logged',(SELECT count(*)=1 FROM lab.draft_activity_calls));
SELECT lab.check('draft: data has no learner UUID column',NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='rtn_private' AND table_name='attempt_drafts' AND column_name IN('user_id','student_user_id','student_id')));
SELECT lab.check('draft: targeted parent erasure has cascade contract',EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='rtn_private.attempt_drafts'::regclass AND contype='f' AND confrelid='rtn_private.attempts'::regclass AND confdeltype='c'));
